#include <bits/stdc++.h>
using namespace std;

void apply(vector<int>& p, int x, int y) {
    int n = p.size();
    vector<int> np;
    for (int i = n - y; i < n; i++) np.push_back(p[i]);
    for (int i = x; i < n - y; i++) np.push_back(p[i]);
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

int main(){
    int n;
    scanf("%d", &n);
    vector<int> p(n);
    for (int i = 0; i < n; i++) scanf("%d", &p[i]);

    vector<pair<int,int>> ops;

    for (int placed = 0; placed < n; placed++) {
        int pos = -1;
        for (int i = placed; i < n; i++) if (p[i] == placed + 1) { pos = i; break; }
        if (pos == placed) continue;

        int remaining = n - placed; // elements from index placed..n-1 matter
        // But operations work on the whole array

        // Step 1: Move element from pos to position n-1
        if (pos < n - 1) {
            // x = pos+1, y = n-1-pos. But x+y = pos+1+n-1-pos = n, need < n.
            // So use x = pos+1, y = n-1-pos-1 = n-pos-2 if n-pos-2 > 0 i.e. pos < n-2
            // After: suffix[y] + middle + prefix[x]. Element at pos goes to end (in prefix block).
            // Actually let's just directly use: x=pos+1, y=n-pos-1 won't work (sum=n).
            // Use x=1, y=n-1-pos if pos>0 and 1+(n-1-pos)<n => n-pos<n => pos>0
            // This puts last (n-1-pos) elems first, then middle, then first elem last.
            // Element was at pos, it's in middle (indices 1..pos), goes to position (n-1-pos)+(pos-1)=n-2... not helpful

            // Better: x=pos, y=n-1-pos, sum=n-1<n, valid if pos>0 and n-1-pos>0 (pos<n-1)
            if (pos > 0 && pos < n - 1) {
                int x = pos, y = n - 1 - pos;
                ops.push_back({x, y});
                apply(p, x, y);
                // Element was at index pos. prefix=[0..pos-1], middle=[pos], suffix=[pos+1..n-1]
                // Result: suffix + middle + prefix. Element at pos is in middle, goes to index y = n-1-pos... 
                // Actually middle is p[x..n-y-1] = p[pos..pos], element is at pos which is middle[0], placed at position y
                for (int i = 0; i < n; i++) if (p[i] == placed + 1) { pos = i; break; }
            }
        }
        // Step 2: Move element from pos to position placed
        if (pos == placed) continue;
        if (pos > placed && placed + (n - pos) < n) {
            int x = placed, y = n - pos;
            if (x > 0 && y > 0 && x + y < n) {
                ops.push_back({x, y});
                apply(p, x, y);
                for (int i = 0; i < n; i++) if (p[i] == placed + 1) { pos = i; break; }
            }
        }
        if (pos != placed && placed == 0 && pos < n - 1) {
            int x = pos, y = 1;
            if (x > 0 && x + 1 < n) {
                ops.push_back({x, y});
                apply(p, x, y);
            }
        }
    }

    printf("%d\n", (int)ops.size());
    for (auto& [x, y] : ops) printf("%d %d\n", x, y);
}
